"""SmartRack - live bike rack status, activity log and theft alarm.
Run:  python app.py      Open: http://localhost:5000  (or http://<pi-ip>:5000)
"""
import sqlite3, time, os, datetime
from flask import Flask, jsonify, request

NUM_RAILS = 6          # <-- number of bike park slots
DB = os.path.join(os.path.dirname(os.path.abspath(__file__)), "smartrack.db")
app = Flask(__name__)


def db():
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    return c


def init():
    c = db()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS rails(id INTEGER PRIMARY KEY, card TEXT, since REAL,
        alarm INTEGER DEFAULT 0, alarm_ts REAL, alarm_reason TEXT);
    CREATE TABLE IF NOT EXISTS users(card TEXT PRIMARY KEY, name TEXT);
    CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL,
        event TEXT, card TEXT, rail INTEGER, note TEXT);
    """)
    for i in range(1, NUM_RAILS + 1):
        c.execute("INSERT OR IGNORE INTO rails(id) VALUES(?)", (i,))
    if c.execute("SELECT COUNT(*) FROM users").fetchone()[0] == 0:
        # <-- put your real card UIDs here
        c.executemany("INSERT INTO users VALUES(?,?)",
                      [("A1B2C3D4", "Anna"), ("E5F6A7B8", "Ben"), ("12345678", "Chris")])
    c.commit(); c.close()


def log(c, event, card=None, rail=None, note=""):
    c.execute("INSERT INTO logs(ts,event,card,rail,note) VALUES(?,?,?,?,?)",
              (time.time(), event, card, rail, note))


def name_of(c, card):
    if not card:
        return None
    r = c.execute("SELECT name FROM users WHERE card=?", (card,)).fetchone()
    return r["name"] if r else card


@app.get("/api/status")
def status():
    c = db()
    rails = []
    for r in c.execute("SELECT * FROM rails ORDER BY id"):
        rails.append(dict(id=r["id"], occupied=bool(r["card"]), card=r["card"],
                          user=name_of(c, r["card"]), since=r["since"],
                          alarm=bool(r["alarm"]), alarm_ts=r["alarm_ts"],
                          alarm_reason=r["alarm_reason"]))
    users = [dict(card=u["card"], name=u["name"]) for u in c.execute("SELECT * FROM users")]
    c.close()
    return jsonify(rails=rails, users=users, now=time.time(),
                   today=datetime.date.today().isoformat())


@app.get("/api/logs")
def logs():
    """Events of one day: /api/logs?date=2026-09-28 (default: today)."""
    day = request.args.get("date") or datetime.date.today().isoformat()
    try:
        start = datetime.datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        return jsonify(error="date must look like 2026-09-28"), 400
    end = start + datetime.timedelta(days=1)
    c = db()
    rows = c.execute("SELECT * FROM logs WHERE ts>=? AND ts<? ORDER BY id DESC LIMIT 500",
                     (start.timestamp(), end.timestamp())).fetchall()
    out = [dict(ts=r["ts"], event=r["event"], card=r["card"], user=name_of(c, r["card"]),
                rail=r["rail"], note=r["note"]) for r in rows]
    c.close()
    return jsonify(date=day, events=out)


@app.post("/api/scan")
def scan():
    """The Pi (or the demo panel) sends: {"card": "A1B2C3D4", "rail": 3}"""
    d = request.get_json(force=True)
    card, rail = str(d.get("card", "")).upper(), int(d.get("rail", 0))
    c = db()
    known = c.execute("SELECT 1 FROM users WHERE card=?", (card,)).fetchone()
    r = c.execute("SELECT * FROM rails WHERE id=?", (rail,)).fetchone()
    if not r:
        c.close(); return jsonify(ok=False, msg="unknown slot"), 404
    if not known:
        log(c, "access denied", card, rail, "unknown card"); result = "denied"
    elif not r["card"]:
        c.execute("UPDATE rails SET card=?, since=? WHERE id=?", (card, time.time(), rail))
        log(c, "parked", card, rail); result = "parked"
    elif r["card"] == card:
        c.execute("UPDATE rails SET card=NULL, since=NULL, alarm=0 WHERE id=?", (rail,))
        log(c, "unlocked", card, rail); result = "unlocked"
    else:
        log(c, "access denied", card, rail, "slot belongs to another card"); result = "denied"
    c.commit(); c.close()
    return jsonify(ok=True, result=result)


@app.post("/api/alarm")
def alarm():
    """Sensor triggers this: {"rail": 3, "reason": "vibration"} or "removed without scan"."""
    d = request.get_json(force=True)
    rail, reason = int(d.get("rail", 0)), d.get("reason", "unauthorized movement")
    c = db()
    r = c.execute("SELECT card FROM rails WHERE id=?", (rail,)).fetchone()
    c.execute("UPDATE rails SET alarm=1, alarm_ts=?, alarm_reason=? WHERE id=?",
              (time.time(), reason, rail))
    log(c, "alarm", r["card"] if r else None, rail, reason)
    c.commit(); c.close()
    return jsonify(ok=True)


@app.post("/api/report")
def report():
    rail = int(request.get_json(force=True).get("rail", 0))
    c = db()
    r = c.execute("SELECT card FROM rails WHERE id=?", (rail,)).fetchone()
    c.execute("UPDATE rails SET alarm=1, alarm_ts=?, alarm_reason=? WHERE id=?",
              (time.time(), "theft reported by owner", rail))
    log(c, "alarm", r["card"] if r else None, rail, "theft reported manually")
    c.commit(); c.close()
    return jsonify(ok=True)


@app.post("/api/ack")
def ack():
    rail = int(request.get_json(force=True).get("rail", 0))
    c = db()
    c.execute("UPDATE rails SET alarm=0 WHERE id=?", (rail,))
    log(c, "alarm cleared", None, rail)
    c.commit(); c.close()
    return jsonify(ok=True)


@app.post("/api/unlock")
def unlock():
    """Manual admin override / demo reset."""
    rail = int(request.get_json(force=True).get("rail", 0))
    c = db()
    c.execute("UPDATE rails SET card=NULL, since=NULL, alarm=0 WHERE id=?", (rail,))
    log(c, "unlocked", None, rail, "manual override")
    c.commit(); c.close()
    return jsonify(ok=True)


@app.get("/")
def index():
    return PAGE


PAGE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>SmartRack</title>
<style>
:root{--bg:#eef1ee;--veil:rgba(238,241,238,.45);--glass:rgba(255,255,255,.88);--ink:#1c2420;--mute:#66726b;--line:#d3dad5;
--free:#1f9d55;--free-bg:#e3f4ea;--busy:#d93a30;--busy-bg:#fce8e6;--card:#fff}
@media(prefers-color-scheme:dark){:root{--bg:#141a17;--veil:rgba(20,26,23,.55);--glass:rgba(28,36,32,.88);--ink:#e8eee9;
--mute:#94a39a;--line:#2b3630;--free:#3ecf7c;--free-bg:#173325;--busy:#ff6b60;--busy-bg:#3a1c1a;--card:#1c2420}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.45 "Trebuchet MS","Segoe UI",sans-serif}
body::before{content:"";position:fixed;inset:-24px;z-index:-1;filter:blur(5px);
background:linear-gradient(var(--veil),var(--veil)),url(data:image/jpeg;base64,) center/cover no-repeat}
main{max-width:980px;margin:0 auto;padding:20px 16px 60px}
.panel{background:var(--glass);border-radius:14px;padding:16px;margin-top:16px;backdrop-filter:blur(6px)}
header.panel{display:flex;align-items:baseline;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-top:0}
h1{margin:0;font-size:1.5rem}
.tag{color:var(--mute);font-size:.9rem}
.count{font-size:2.6rem;font-weight:700;letter-spacing:-1px}
.count small{font-size:1rem;font-weight:400;color:var(--mute);letter-spacing:0}
h2{font-size:1.05rem;margin:0 0 10px}
#banner{display:none;background:var(--busy);color:#fff;border-radius:10px;padding:12px 16px;margin-top:16px}
#banner.on{display:block;animation:pulse 1.2s infinite}
@keyframes pulse{50%{opacity:.75}}
@media(prefers-reduced-motion:reduce){#banner.on{animation:none}}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}
.tile{border-radius:10px;padding:12px 14px;border:2px solid var(--free);background:var(--free-bg);min-height:118px}
.tile.busy{border-color:var(--busy);background:var(--busy-bg)}
.tile.alarm{outline:4px solid var(--busy)}
.tile b{font-size:1.1rem}.tile .st{font-weight:700;color:var(--free)}
.tile.busy .st{color:var(--busy)}
.tile .meta{font-size:.85rem;color:var(--mute)}
button{font:inherit;cursor:pointer;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:8px;padding:6px 12px}
button:disabled{opacity:.45;cursor:default}
button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--free);outline-offset:2px}
button.red{background:var(--busy);border-color:var(--busy);color:#fff}
.tile button{margin-top:8px;font-size:.8rem;padding:4px 8px}
.days{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px}
.days .lbl{font-weight:700;margin-right:6px}.days .n{color:var(--mute);font-size:.9rem}
input[type=date]{font:inherit;padding:5px;border-radius:8px;border:1px solid var(--line);background:var(--card);color:var(--ink)}
ul{list-style:none;margin:0;padding:0;background:var(--card);border:1px solid var(--line);border-radius:10px}
#log{max-height:320px;overflow-y:auto}
li{display:flex;gap:12px;padding:8px 14px;border-bottom:1px solid var(--line);font-size:.92rem}
li:last-child{border:0}
li .t{color:var(--mute);min-width:64px}
li .e{font-weight:700;min-width:110px}
.e.alarm,.e.denied{color:var(--busy)}.e.parked{color:var(--free)}
.demo{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
select{font:inherit;padding:6px;border-radius:8px;border:1px solid var(--line);background:var(--card);color:var(--ink)}
</style></head><body><main>
<header class="panel"><div><h1>SmartRack</h1><div class="tag">Live bike parking</div></div>
<div class="count"><span id="free">-</span><small> of <span id="total">-</span> slots free</small></div></header>
<div id="banner" role="alert"></div>
<section class="panel"><h2>Bike park slots</h2><div class="grid" id="grid"></div></section>
<section class="panel"><h2>Activity log</h2>
 <div class="days">
  <button id="prev" onclick="shift(-1)" aria-label="Previous day">&lsaquo; Previous</button>
  <input type="date" id="dpick" onchange="setDay(this.value)" aria-label="Pick a day">
  <button id="next" onclick="shift(1)" aria-label="Next day">Next &rsaquo;</button>
  <button id="tbtn" onclick="setDay(today)">Today</button>
  <span class="lbl" id="dlabel"></span><span class="n" id="dcount"></span>
 </div>
 <ul id="log"><li>Loading...</li></ul></section>
<section class="panel"><h2>Demo controls</h2>
<div class="demo">
 <select id="dc" aria-label="Card"></select>
 <select id="dr" aria-label="Bike park slot"></select>
 <button onclick="scan()">Scan card</button>
 <button onclick="scan('DEADBEEF')">Scan unknown card</button>
 <button class="red" onclick="post('/api/alarm',{rail:+dr.value,reason:'removed without scan'})">Simulate theft</button>
</div></section>
</main>
<script>
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const hm=t=>new Date(t*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
const iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
let day=null,today=null,follow=true,built=false;
const since=t=>iso(new Date(t*1000))===today?hm(t):new Date(t*1000).toLocaleDateString([], {day:'numeric',month:'short'})+' '+hm(t);
const label=d=>new Date(d+'T12:00:00').toLocaleDateString([], {weekday:'long',day:'numeric',month:'long',year:'numeric'});
async function post(url,body){await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});refresh()}
function scan(card){post('/api/scan',{card:card||$('dc').value,rail:+$('dr').value})}
function setDay(v){if(!v||v>today)return;day=v;follow=(v===today);refresh()}
function shift(n){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);setDay(iso(d))}
async function refresh(){
 try{
  const s=await (await fetch('/api/status')).json();
  today=s.today;if(follow||!day){day=today;follow=true}
  const l=await (await fetch('/api/logs?date='+day)).json();
  const free=s.rails.filter(r=>!r.occupied).length;
  $('free').textContent=free;$('total').textContent=s.rails.length;
  const alarms=s.rails.filter(r=>r.alarm);
  const b=$('banner');
  if(alarms.length){b.className='on';
   b.innerHTML=alarms.map(r=>`<b>ALARM at bike park slot ${r.id}</b> at ${since(r.alarm_ts)} (${esc(r.alarm_reason)}) `+
    `<button onclick="post('/api/ack',{rail:${r.id}})">Clear alarm</button>`).join('<br>')}
  else b.className='';
  $('grid').innerHTML=s.rails.map(r=>`<div class="tile ${r.occupied?'busy':''} ${r.alarm?'alarm':''}">
   <b>Bike park slot ${r.id}</b><div class="st">${r.occupied?'Occupied':'Free'}</div>
   <div class="meta">${r.occupied?esc(r.user)+'<br>since '+since(r.since):'Ready to park'}</div>
   ${r.occupied?`<button onclick="post('/api/report',{rail:${r.id}})">Report theft</button>`:''}
   ${r.occupied?`<button onclick="post('/api/unlock',{rail:${r.id}})">Unlock</button>`:''}</div>`).join('');
  if(!built){$('dc').innerHTML=s.users.map(u=>`<option value="${esc(u.card)}">${esc(u.name)}</option>`).join('');
   $('dr').innerHTML=s.rails.map(r=>`<option value="${r.id}">Bike park slot ${r.id}</option>`).join('');built=true}
  const dp=$('dpick');if(document.activeElement!==dp)dp.value=day;dp.max=today;
  $('next').disabled=day>=today;$('tbtn').disabled=follow;
  $('dlabel').textContent=label(day)+(day===today?' (today)':'');
  $('dcount').textContent=l.events.length+' events';
  const pos=$('log').scrollTop;
  $('log').innerHTML=l.events.length?l.events.map(e=>`<li><span class="t">${hm(e.ts)}</span>
   <span class="e ${e.event.includes('denied')?'denied':e.event}">${esc(e.event)}</span>
   <span>${esc(e.user||'-')} &middot; slot ${e.rail??'-'} ${e.note?'&middot; '+esc(e.note):''}</span></li>`).join('')
   :(day===today?'<li>No events yet today. Use the demo controls to scan a card.</li>':'<li>No events on this day.</li>');
  $('log').scrollTop=pos;
 }catch(e){}
}
refresh();setInterval(refresh,1500);
</script></body></html>
"""

if __name__ == "__main__":
    init()
    app.run(host="0.0.0.0", port=5000)
